begin;
create table if not exists hq.legal_licenses(id uuid primary key default gen_random_uuid(),legal_entity_id uuid not null references hq.legal_entities(id),platform_id uuid references hq.platforms(id),name text not null,authority text,license_number text,issued_on date,expires_on date,status text not null default 'active' check(status in('pending','active','expiring','expired','suspended','cancelled')),document_id uuid references hq.documents(id),owner_employee_id uuid references hq.employees(id),created_at timestamptz not null default now());
create table if not exists hq.legal_cases(id uuid primary key default gen_random_uuid(),legal_entity_id uuid not null references hq.legal_entities(id),platform_id uuid references hq.platforms(id),case_number text,title text not null,case_type text not null,counterparty text,court_or_authority text,status text not null default 'open' check(status in('open','under_review','hearing','settled','won','lost','closed')),risk_level text not null default 'medium' check(risk_level in('low','medium','high','critical')),next_deadline timestamptz,owner_employee_id uuid references hq.employees(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists hq.corporate_policies(id uuid primary key default gen_random_uuid(),legal_entity_id uuid not null references hq.legal_entities(id),title text not null,category text not null,version integer not null default 1,status text not null default 'draft' check(status in('draft','under_review','approved','retired')),effective_on date,review_due_on date,document_id uuid references hq.documents(id),owner_employee_id uuid references hq.employees(id),approved_by uuid references hq.employees(id),created_at timestamptz not null default now());
create table if not exists hq.legal_obligations(id uuid primary key default gen_random_uuid(),legal_entity_id uuid not null references hq.legal_entities(id),platform_id uuid references hq.platforms(id),title text not null,obligation_type text not null,authority text,due_on date,status text not null default 'pending' check(status in('pending','in_progress','compliant','overdue','waived')),owner_employee_id uuid references hq.employees(id),evidence_document_id uuid references hq.documents(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
do $$ declare t text; begin foreach t in array array['legal_licenses','legal_cases','corporate_policies','legal_obligations'] loop execute format('alter table hq.%I enable row level security',t); execute format('revoke all on hq.%I from public,anon,authenticated',t); execute format('grant all on hq.%I to service_role',t); end loop; end $$;
create index if not exists idx_hq_legal_deadlines on hq.legal_cases(next_deadline,status);create index if not exists idx_hq_legal_obligations_due on hq.legal_obligations(due_on,status);create index if not exists idx_hq_licenses_expiry on hq.legal_licenses(expires_on,status);
commit;
